        "$MAINTENANCE_CRON" \
        "$BACKUP_CRON" \
        "/etc/cron.d/gnss-caster-cert-renew" \
        "/etc/logrotate.d/gnss-caster" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE" \
        "$PRIVILEGED_HELPER" \
        "$BASE/main.py" \
        "$BASE/requirements.txt" \
        "$BASE/sqlite-functions.sh" \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/release-update.py" \
