nginx_https_listen_directives() {
    # nginx >= 1.25 deprecates "listen ... http2" in favour of a separate
    # "http2 on;" directive; older builds do not know "http2" as a directive at
    # all and refuse to start. Pick the form the installed nginx understands.
    local version_string major minor
    version_string=$(nginx -v 2>&1 | sed -n 's|.*nginx/\([0-9]*\.[0-9]*\).*|\1|p')
    major="${version_string%%.*}"
    minor="${version_string##*.}"

    if [ -n "$major" ] && [ -n "$minor" ] && { [ "$major" -gt 1 ] || { [ "$major" -eq 1 ] && [ "$minor" -ge 25 ]; }; }; then
        printf '    listen 443 ssl default_server;\n    http2 on;'
    else
        printf '    listen 443 ssl http2 default_server;'
    fi
}

write_nginx_https_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
    local https_listen
    https_listen=$(nginx_https_listen_directives)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (HTTPS)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
    server_name $NGINX_SERVER_NAME;
    server_tokens off;

    location /.well-known/acme-challenge/ {
        root $LE_WEBROOT;
    }

    location / {
        return 301 https://\$host\$request_uri;
    }
}

server {
$https_listen
    server_name $NGINX_SERVER_NAME;
    server_tokens off;
    client_max_body_size 2m;
    limit_conn gnss_conn_per_ip 30;

    ssl_certificate $SSL_CERT_PATH;
    ssl_certificate_key $SSL_KEY_PATH;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;

    location = /login {
        limit_req zone=gnss_login burst=10 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    # Throttle 2FA code submission to blunt TOTP brute-force (shares the login
    # rate-limit bucket per client IP; not covered by the exact "= /login" match).
    location = /login/2fa {
        limit_req zone=gnss_login burst=5 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    location / {
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;

        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    location /api/ {
        limit_req zone=gnss_api burst=30 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location /health {
        access_log off;
        proxy_pass $backend_url/api/health;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
}

nginx_site_contains_server_name() {
    local site_file="$1"
    local desired_name="$2"

    awk -v desired="$desired_name" '
        /^[[:space:]]*server_name[[:space:]]+/ {
            for (i = 2; i <= NF; i++) {
                gsub(/;/, "", $i)
                if ($i == desired) {
                    found = 1
                }
            }
        }
        END { exit found ? 0 : 1 }
    ' "$site_file" 2>/dev/null
}

check_nginx_config_conflicts() {
    local desired_name="$NGINX_SERVER_NAME"
    local site_file
    local site_target
    local gnss_target
    local conflict_found=0

    if [ -z "$desired_name" ] || [ "$desired_name" = "_" ]; then
        return 0
    fi

    gnss_target=$(readlink -f "$NGINX_AVAILABLE" 2>/dev/null || printf '%s' "$NGINX_AVAILABLE")

    for site_file in /etc/nginx/sites-enabled/* /etc/nginx/conf.d/*.conf; do
        [ -e "$site_file" ] || [ -L "$site_file" ] || continue

        site_target=$(readlink -f "$site_file" 2>/dev/null || printf '%s' "$site_file")
        if [ "$site_target" = "$gnss_target" ] || [ "$site_file" = "$NGINX_ENABLED" ] || [ "$site_file" = "$NGINX_SECURITY_CONF" ]; then
            continue
        fi

        if nginx_site_contains_server_name "$site_file" "$desired_name"; then
            echo "ERROR: Nginx server_name '$desired_name' is already configured in $site_file"
            conflict_found=1
        fi
    done

    if [ "$conflict_found" -ne 0 ]; then
        echo "Choose a different TLS_DOMAIN/server_name or disable the conflicting nginx site before installing."
        exit 1
    fi
}

check_nginx_public_port_conflicts() {
    local port
    local listeners
    local non_nginx_listeners

    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi

    for port in 80 443; do
        if [ "$port" = "443" ] && ! grep -Eq 'listen[[:space:]]+443[[:space:]]+ssl' "$NGINX_AVAILABLE" 2>/dev/null; then
            continue
        fi

        listeners=$(ss -ltnp 2>/dev/null | grep -E "[:.]${port}[[:space:]]" || true)
        [ -n "$listeners" ] || continue

        non_nginx_listeners=$(printf '%s\n' "$listeners" | grep -vi 'nginx' || true)
        if [ -n "$non_nginx_listeners" ]; then
            echo "ERROR: Public HTTP(S) port $port is already held by a non-nginx process:"
            printf '%s\n' "$non_nginx_listeners" | sed 's/^/  /'
            echo "Stop the conflicting service or move GNSS Caster behind the existing reverse proxy."
            exit 1
        fi
    done
}

disable_default_nginx_site() {
    # Debian/Ubuntu ship /etc/nginx/sites-enabled/default listening on port 80
    # as "default_server". A request by IP address (no matching server_name)
    # therefore lands on the nginx welcome page instead of the caster - or on
    # its HTTP->HTTPS redirect. Disable it, remembering that we did so, so the
    # uninstaller can put it back exactly as it was.
    local default_site="/etc/nginx/sites-enabled/default"

    [ -e "$default_site" ] || return 0

    echo "Disabling the default nginx site (it would shadow GNSS Caster on port 80)."
    if [ -L "$default_site" ]; then
        rm -f "$default_site"
        touch "$BASE/.nginx-default-was-symlink" 2>/dev/null || true
    else
        mv -f "$default_site" "$default_site.gnss-caster.disabled"
        touch "$BASE/.nginx-default-was-file" 2>/dev/null || true
    fi
}

apply_nginx_config() {
    check_nginx_config_conflicts
    check_nginx_public_port_conflicts
    write_nginx_security_config
    strip_crlf "$NGINX_AVAILABLE"
    strip_crlf "$NGINX_SECURITY_CONF"
    ensure_backup_upload_nginx_location
    ln -sf "$NGINX_AVAILABLE" "$NGINX_ENABLED" 2>/dev/null || true
    disable_default_nginx_site
    nginx -t
    systemctl reload nginx || systemctl restart nginx
}

ensure_backup_upload_nginx_location() {
    python3 - "$NGINX_AVAILABLE" << 'PY_UPLOAD_NGINX'
import re
import sys
from pathlib import Path
path = Path(sys.argv[1])
source = path.read_text()
if 'location = /api/system/backups/upload' not in source:
    pattern = r'(?m)^([ \t]*)location /api/\s*\{([^{}]*)\}'
    def add_upload(match):
        indent, body = match.groups()
        if 'proxy_pass ' not in body:
            raise SystemExit('API nginx location has no upstream')
        upload = (indent + 'location = /api/system/backups/upload {\n' +
                  indent + '    client_max_body_size 129m;\n' +
                  indent + '    client_body_timeout 120s;\n' +
                  body + '\n' + indent + '}\n\n')
        return upload + match.group(0)
    source, count = re.subn(pattern, add_upload, source)
    if not count:
        raise SystemExit('Cannot configure backup upload: nginx API location missing')
    path.write_text(source)
PY_UPLOAD_NGINX
}

setup_selfsigned_tls() {
    # Generate a 4096-bit self-signed certificate for HTTPS with no external CA.
    # Intended for LAN or closed deployments (browsers will warn about trust).
    # The private key is written mode 0600; TLS_SELF_SIGNED_DAYS sets validity.
    mkdir -p /etc/ssl/private /etc/ssl/certs "$LE_WEBROOT"

    local cert_cn
    cert_cn="${TLS_DOMAIN:-$(hostname -f 2>/dev/null || hostname || echo gnss-caster.local)}"

    # Use only O= and CN= to avoid hardcoded country/state/city placeholders
    # that are meaningless or confusing for non-US deployments.
    openssl req -x509 -nodes -days "$TLS_SELF_SIGNED_DAYS" -newkey rsa:4096 \
        -keyout "$SELF_SIGNED_KEY" \
        -out "$SELF_SIGNED_CERT" \
        -subj "/O=GNSS Caster/CN=$cert_cn" 2>/dev/null

    chmod 600 "$SELF_SIGNED_KEY" 2>/dev/null || true
    chmod 644 "$SELF_SIGNED_CERT" 2>/dev/null || true

    SSL_CERT_PATH="$SELF_SIGNED_CERT"
    SSL_KEY_PATH="$SELF_SIGNED_KEY"
}

setup_existing_tls() {
    # Use a certificate the operator already has (their own CA, a wildcard, a
    # corporate PKI, or an externally-managed ACME cert). Files are validated in
    # validate_tls_config; nginx is pointed at the operator's canonical paths
    # rather than copies, so certificate renewals they perform are picked up on
    # the next "systemctl reload nginx" with no reinstall.
    if [ ! -r "$TLS_CERT_FILE" ] || [ ! -r "$TLS_KEY_FILE" ]; then
        echo "ERROR: certificate or key became unreadable: $TLS_CERT_FILE / $TLS_KEY_FILE"
        exit 1
    fi

    SSL_CERT_PATH="$TLS_CERT_FILE"
    SSL_KEY_PATH="$TLS_KEY_FILE"
    echo "Using existing certificate: $SSL_CERT_PATH"
}

setup_letsencrypt_tls() {
    # Obtain a trusted certificate from Let's Encrypt via the webroot (HTTP-01)
    # challenge: a temporary nginx config serves the challenge files under
    # LE_WEBROOT, certbot issues the cert for TLS_DOMAIN, and a cron job plus
    # certbot.timer renew it automatically (reloading nginx on deploy). Requires
    # TLS_DOMAIN to resolve publicly to this host and TLS_EMAIL for the account.
    mkdir -p "$LE_WEBROOT"
    chown -R www-data:www-data "$LE_WEBROOT" 2>/dev/null || true

    write_nginx_letsencrypt_bootstrap_config
    apply_nginx_config

    certbot certonly \
        --webroot -w "$LE_WEBROOT" \
        --agree-tos \
        --non-interactive \
        --email "$TLS_EMAIL" \
        --keep-until-expiring \
        -d "$TLS_DOMAIN"

    SSL_CERT_PATH="/etc/letsencrypt/live/$TLS_DOMAIN/fullchain.pem"
    SSL_KEY_PATH="/etc/letsencrypt/live/$TLS_DOMAIN/privkey.pem"

    if [ ! -f "$SSL_CERT_PATH" ] || [ ! -f "$SSL_KEY_PATH" ]; then
        echo "ERROR: Let's Encrypt certificate files not found in /etc/letsencrypt/live/$TLS_DOMAIN"
        exit 1
    fi

    cat > /etc/cron.d/gnss-caster-cert-renew << EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
17 3 * * * root certbot renew --quiet --deploy-hook "systemctl reload nginx"
EOF
    chmod 644 /etc/cron.d/gnss-caster-cert-renew
    systemctl enable certbot.timer --now >/dev/null 2>&1 || true
}

remove_gnss_cron_jobs() {
    rm -f "$MAINTENANCE_CRON" "$BACKUP_CRON"

    if ! command -v crontab >/dev/null 2>&1; then
        return
    fi

    local tmp_cron
    tmp_cron=$(mktemp)

    crontab -l 2>/dev/null | \
        grep -v '/opt/gnss-caster/monitor.sh' | \
        grep -v '/opt/gnss-caster/watchdog.sh' | \
        grep -v '/opt/gnss-caster/backup.sh' | \
        grep -v '/opt/gnss-caster/update.sh' > "$tmp_cron" || true

    if [ -s "$tmp_cron" ]; then
        crontab "$tmp_cron" || true
    else
        crontab -r 2>/dev/null || true
    fi

    rm -f "$tmp_cron"
}

write_ufw_application_profile() {
    mkdir -p /etc/ufw/applications.d

cat > "$UFW_APP_PROFILE" << EOF
[GNSS Caster Web]
title=GNSS Caster Web Interface
description=GNSS Caster web UI via nginx reverse proxy
ports=80,443/tcp

[GNSS Caster NTRIP]
title=GNSS Caster NTRIP Service
description=GNSS Caster rover correction stream service
ports=${INSTALL_NTRIP_PORT}/tcp

[GNSS Caster Full]
title=GNSS Caster Full Service
description=GNSS Caster web UI and NTRIP service
ports=80,443,${INSTALL_NTRIP_PORT}/tcp
EOF

    chmod 644 "$UFW_APP_PROFILE" 2>/dev/null || true

    if command -v ufw >/dev/null 2>&1; then
        ufw app update "GNSS Caster Web" >/dev/null 2>&1 || true
        ufw app update "GNSS Caster NTRIP" >/dev/null 2>&1 || true
        ufw app update "GNSS Caster Full" >/dev/null 2>&1 || true

        # The web backend (Waitress) must only be reachable through nginx.
        # When the firewall is active, explicitly deny external access to the
        # backend port so it cannot be hit directly even if it ever binds wider
        # than 127.0.0.1. This is a no-op when ufw is inactive.
        if ufw status 2>/dev/null | grep -qi '^Status: active'; then
            ufw deny "${INSTALL_WEB_PORT}/tcp" >/dev/null 2>&1 || true
            echo "Firewall: denied external access to web backend port ${INSTALL_WEB_PORT}/tcp (use nginx)."
        else
            echo "Firewall inactive: skipping deny rule for web backend port ${INSTALL_WEB_PORT}/tcp."
            echo "If you enable ufw later, run: ufw deny ${INSTALL_WEB_PORT}/tcp"
        fi
    fi
}

setup_fail2ban() {
    local fail2ban_jail_enabled="false"

    if [ "$ENABLE_FAIL2BAN" = "1" ]; then
        fail2ban_jail_enabled="true"
    fi

    mkdir -p /etc/fail2ban/filter.d /etc/fail2ban/jail.d

cat > "$FAIL2BAN_FILTER" << 'EOF'
[Definition]
failregex = ^.*Failed login attempt for user .* from <HOST>.*$
ignoreregex =
EOF

cat > "$FAIL2BAN_JAIL" << EOF
[gnss-caster-auth]
enabled = $fail2ban_jail_enabled
filter = gnss-caster-auth
logpath = /var/log/gnss-caster/app.log
backend = auto
findtime = 10m
bantime = 1h
maxretry = 8
port = http,https
EOF

    chmod 644 "$FAIL2BAN_FILTER" "$FAIL2BAN_JAIL" 2>/dev/null || true

    if [ "$ENABLE_FAIL2BAN" = "1" ]; then
        systemctl enable fail2ban --now >/dev/null 2>&1 || true
        systemctl restart fail2ban >/dev/null 2>&1 || true
        echo "Fail2ban enabled with GNSS Caster auth jail."
        return
    fi

    if [ "$FAIL2BAN_WAS_ACTIVE" -eq 1 ]; then
        fail2ban-client reload >/dev/null 2>&1 || systemctl restart fail2ban >/dev/null 2>&1 || true
        echo "Fail2ban was already active; GNSS Caster auth jail is disabled by default and configuration was reloaded."
        echo "If SSH drops persist, review existing fail2ban SSH jails with: fail2ban-client status"
        return
    fi

    if [ "$FAIL2BAN_DISABLED_BY_INSTALLER" -eq 1 ]; then
        echo "Fail2ban service was left unchanged; GNSS Caster jail is disabled because GNSS_CASTER_ENABLE_FAIL2BAN is not set."
    elif [ "$FAIL2BAN_WAS_PRESENT" -eq 1 ]; then
        echo "Fail2ban was present but inactive; GNSS Caster auth jail is disabled and service was left inactive."
    else
        echo "Fail2ban configuration installed with GNSS Caster auth jail disabled; package/service was not enabled."
    fi
    echo "Set GNSS_CASTER_ENABLE_FAIL2BAN=1 before install to enable fail2ban hardening."
}

get_config_value() {
    local config_key="$1"
    local default_value="$2"
    local config_file="$INST/config.yaml"
    local config_value=""

    if [ -f "$config_file" ]; then
        config_value=$(awk -F': *' -v lookup_key="$config_key" '
            $0 ~ "^[[:space:]]*" lookup_key ":[[:space:]]*" {
                value = $2
                sub(/[[:space:]]+#.*$/, "", value)
                gsub(/[[:space:]]+$/, "", value)
                print value
                exit
            }
        ' "$config_file" 2>/dev/null)
    fi

    if [ -n "$config_value" ]; then
        printf '%s\n' "$config_value"
    else
        printf '%s\n' "$default_value"
    fi
}

get_system_setting_from_db() {
    local setting_key="$1"
    local default_value="$2"
    local db_file="$INST/db.sqlite"
    local setting_value=""

    # Whitelist: only allow known safe keys to prevent SQL injection.
    case "$setting_key" in
        ntrip_enabled|bluetooth_enabled|bluetooth_discoverable|\
        auto_backup|backup_interval|log_retention|data_retention|\
        max_connections|watchdog_enabled|auto_update_enabled)
            ;;
        *)
            echo "ERROR: get_system_setting_from_db: unknown key '$setting_key'" >&2
            printf '%s\n' "$default_value"
            return 0
            ;;
    esac

    if [ -f "$db_file" ] && command -v sqlite3 >/dev/null 2>&1; then
        setting_value=$(sqlite3 "$db_file" \
            "SELECT value FROM system_setting WHERE key='$setting_key' LIMIT 1;" \
            2>/dev/null || true)
    fi

    if [ -n "$setting_value" ]; then
        printf '%s\n' "$setting_value"
    else
        printf '%s\n' "$default_value"
    fi
}

backup_interval_to_cron_expression() {
    local interval_seconds="$1"
    local interval_minutes
    local interval_hours
    local interval_days

    case "$interval_seconds" in
        ''|*[!0-9]*)
            interval_seconds=86400
            ;;
    esac

    if [ "$interval_seconds" -lt 3600 ]; then
        interval_seconds=3600
    fi

    interval_minutes=$(( (interval_seconds + 30) / 60 ))
    if [ "$interval_minutes" -lt 60 ]; then
        interval_minutes=60
    fi

    if [ "$interval_minutes" -lt 60 ]; then
        printf '*/%s * * * *\n' "$interval_minutes"
        return
    fi

    if [ "$interval_minutes" -lt 1440 ] && [ $((interval_minutes % 60)) -eq 0 ]; then
        interval_hours=$((interval_minutes / 60))
        if [ "$interval_hours" -lt 1 ]; then
            interval_hours=1
        fi
        if [ "$interval_hours" -eq 24 ]; then
            printf '0 2 * * *\n'
            return
        fi
        printf '0 */%s * * *\n' "$interval_hours"
        return
    fi

    if [ $((interval_minutes % 1440)) -eq 0 ]; then
        interval_days=$((interval_minutes / 1440))
        if [ "$interval_days" -lt 1 ]; then
            interval_days=1
        fi
        if [ "$interval_days" -le 28 ]; then
            printf '0 2 */%s * *\n' "$interval_days"
            return
        fi
    fi

    printf '0 2 * * *\n'
}

migrate_bootstrap_admin_password_location() {
    local config_file="$INST/config.yaml"
    local python_config_file="$INST/config.py"
    local tmp_config

    mkdir -p "$INST"

    if [ -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" ] && [ ! -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
        echo "Migrating bootstrap credentials to $BOOTSTRAP_ADMIN_PASSWORD_FILE"
        cp -a "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" "$BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || \
            cp "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" "$BOOTSTRAP_ADMIN_PASSWORD_FILE"
    fi

    if [ -f "$config_file" ]; then
        if grep -Eq '^[[:space:]]*bootstrap_admin_password_file:' "$config_file"; then
            sed -i "s|^[[:space:]]*bootstrap_admin_password_file:.*|  bootstrap_admin_password_file: $BOOTSTRAP_ADMIN_PASSWORD_FILE|" "$config_file"
        elif grep -Eq '^security:[[:space:]]*$' "$config_file"; then
            tmp_config=$(mktemp)
            awk -v bootstrap_path="$BOOTSTRAP_ADMIN_PASSWORD_FILE" '
                /^security:[[:space:]]*$/ {
                    print
                    print "  bootstrap_admin_password_file: " bootstrap_path
                    next
                }
                { print }
            ' "$config_file" > "$tmp_config"
            cat "$tmp_config" > "$config_file"
            rm -f "$tmp_config"
        fi
    fi

    if [ -f "$python_config_file" ]; then
        sed -i "s|/etc/gnss-caster/initial-admin-password|$BOOTSTRAP_ADMIN_PASSWORD_FILE|g" "$python_config_file"
    fi

    if [ -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" ] && [ -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
        rm -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || true
        rmdir /etc/gnss-caster 2>/dev/null || true
    fi
}

set_runtime_permissions() {
    echo "Setting permissions..."

    migrate_bootstrap_admin_password_location

    chown root:"$SERVICE_GROUP" "$BASE"
    chmod 755 "$BASE"

    chown -R root:root "$APP" "$VENV" 2>/dev/null || true
    find "$APP" -type d -exec chmod 755 {} + 2>/dev/null || true
    find "$APP" -type f -exec chmod 644 {} + 2>/dev/null || true
    find "$VENV" -type d -exec chmod 755 {} + 2>/dev/null || true
    find "$VENV" -type f -exec chmod u+rw,go+r {} + 2>/dev/null || true
    find "$VENV/bin" -type f -exec chmod u+rw,go+rx {} + 2>/dev/null || true

    chmod 755 \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/diagnose.sh" \
        "$BASE/repair.sh" \
        "$BASE/status.sh" 2>/dev/null || true
    chown root:root "$PRIVILEGED_HELPER" 2>/dev/null || true
    chmod 750 "$PRIVILEGED_HELPER" 2>/dev/null || true
    chmod 700 "$BASE/gnss-caster-installer.sh" 2>/dev/null || true
    chmod 644 \
        "$BASE/main.py" \
        "$BASE/requirements.txt" 2>/dev/null || true

    chown -R root:"$SERVICE_GROUP" "$INST" 2>/dev/null || true
    find "$INST" -type d -exec chmod 770 {} + 2>/dev/null || true
    chmod 640 "$INST/config.yaml" "$INST/config.py" 2>/dev/null || true
    chmod 660 "$INST/db.sqlite" "$INST/db.sqlite-wal" "$INST/db.sqlite-shm" 2>/dev/null || true
    chmod 660 "$INST/notifications.sqlite" "$INST/notifications.sqlite-journal" 2>/dev/null || true
    chmod 600 "$INSTALL_REPORT" 2>/dev/null || true
    chown -R root:"$SERVICE_GROUP" "$BACKUP_DIR" 2>/dev/null || true
    chmod 770 "$BACKUP_DIR" 2>/dev/null || true
    chmod 640 "$BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || true
    # secret.env must be root:root 600 — not readable by service user via filesystem,
    # but loaded by systemd (which reads it as root before dropping privileges).
    chown root:root "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    chmod 600 "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    find "$INST" -maxdepth 1 -type f -name 'secret.env.bak-*' \
        -exec chown root:root {} + -exec chmod 600 {} +
    chmod 600 /etc/ssl/private/gnss-caster.key 2>/dev/null || true

    touch \
        "$LOG_DIR/app.log" \
        "$LOG_DIR/error.log" \
        "$LOG_DIR/access.log" \
        "$LOG_DIR/backup.log" \
        "$LOG_DIR/restore.log" \
        "$LOG_DIR/update.log" \
        "$LOG_DIR/watchdog.log"
    chown -R root:"$SERVICE_GROUP" "$LOG_DIR"
    # The service may append existing logs, but cannot replace root log targets.
    chmod 750 "$LOG_DIR"
    chmod 660 "$LOG_DIR"/*.log 2>/dev/null || true
}

verify_maintenance_socket() {
    systemctl is-active --quiet gnss-caster-maintenance.socket || return 1
    runuser -u "$SERVICE_USER" -- /usr/bin/python3 -I - "$APP/maintenance.py" << 'PY_BROKER_PING'
import importlib.util
import sys
spec = importlib.util.spec_from_file_location('maintenance_transport', sys.argv[1])
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
result = module.run(['ping'], timeout=10)
if result.returncode != 0 or result.stdout != 'maintenance protocol 1':
    raise SystemExit('Maintenance broker probe failed')
PY_BROKER_PING
}

run_install_smoke_tests() {
    if ! verify_maintenance_socket; then
        echo 'ERROR: Maintenance socket is unavailable to the service account'
        return 1
    fi
    local web_port
    local ntrip_port
    local health_url
    local attempt=1
    local max_attempts=15
    # Each flag: 0 = check not yet passed, 1 = check passed
    local service_pass=0
    local web_pass=0
    local ntrip_pass=0
    local bootstrap_pass=0

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")
    health_url="http://127.0.0.1:${web_port}/api/health"

    while [ "$attempt" -le "$max_attempts" ]; do
        service_pass=0
        web_pass=0
        ntrip_pass=0
        bootstrap_pass=0

        systemctl is-active --quiet gnss-caster  && service_pass=1
        curl -sS --max-time 5 -f "$health_url" >/dev/null 2>&1 && web_pass=1
        ss -ltn | grep -Eq ":${ntrip_port}[[:space:]]" && ntrip_pass=1

        if [ "$EXPECT_BOOTSTRAP_ADMIN_PASSWORD" -eq 0 ] || [ -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
            bootstrap_pass=1
        fi

        if [ $service_pass -eq 1 ] && [ $web_pass -eq 1 ] && [ $ntrip_pass -eq 1 ] && [ $bootstrap_pass -eq 1 ]; then
            echo "Smoke test passed: service active, API healthy, NTRIP port ${ntrip_port} listening."
            return 0
        fi

        if [ "$attempt" -lt "$max_attempts" ]; then
            sleep 2
        fi
        attempt=$((attempt + 1))
    done

    echo "Smoke test failed."
    [ $service_pass -eq 0 ]   && echo " - systemd service is not active"
    [ $web_pass -eq 0 ]       && echo " - backend health check failed: $health_url"
    [ $ntrip_pass -eq 0 ]     && echo " - NTRIP port is not listening: $ntrip_port"
    if [ $bootstrap_pass -eq 0 ]; then
        echo " - bootstrap credentials file not found: $BOOTSTRAP_ADMIN_PASSWORD_FILE"
    fi

    echo ""
    echo "Recent service status:"
    systemctl --no-pager --full status gnss-caster 2>/dev/null | tail -n 20 || true
    echo ""
    echo "Recent application log:"
    tail -n 20 "$LOG_DIR/app.log" 2>/dev/null || true

    return 1
}

uninstall_safety_backup() {
    # Create a safety backup of the database, instance data, and existing
    # backups before they are deleted, unless the operator opted into a purge.
    local safety_root="/var/backups/gnss-caster"
    local ts
    local safety_dir

    if [ ! -d "$INST" ] && [ ! -d "$BACKUP_DIR" ]; then
        echo "No instance data found; skipping safety backup."
        return 0
    fi

    ts=$(date +%Y%m%d_%H%M%S)
    safety_dir="$safety_root/uninstall-$ts"

    mkdir -p "$safety_dir" 2>/dev/null || {
        echo "WARNING: Unable to create safety backup directory $safety_dir; continuing without it."
        return 0
    }
    chmod 700 "$safety_root" "$safety_dir" 2>/dev/null || true

    if [ -d "$INST" ]; then
        cp -a "$INST" "$safety_dir/instance" 2>/dev/null || \
            echo "WARNING: Unable to copy instance data into safety backup."
    fi

    if [ -d "$BACKUP_DIR" ]; then
        cp -a "$BACKUP_DIR" "$safety_dir/backups" 2>/dev/null || \
            echo "WARNING: Unable to copy backups into safety backup."
    fi

    echo "Safety backup created before uninstall: $safety_dir"
    echo "Remove it manually once you have confirmed it is no longer needed."
}

run_uninstall() {
    echo "=== GNSS CASTER UNINSTALL MODE ==="

    if [ "$PURGE_DATA" = "1" ]; then
        echo "Purge mode enabled: instance data, database, and backups WILL be deleted."
    else
        echo "Safe mode: /opt/gnss-caster is removed, and data is copied to a safety backup first."
        echo "Use --purge (or GNSS_CASTER_PURGE=1) to remove all data permanently."
    fi
    echo "Removing GNSS Caster service and files..."

    echo "Stopping and disabling systemd service..."
    systemctl stop gnss-caster >/dev/null 2>&1 || true
    systemctl disable gnss-caster >/dev/null 2>&1 || true
    systemctl stop gnss-caster-maintenance.socket >/dev/null 2>&1 || true
    systemctl stop 'gnss-caster-maintenance@*.service' >/dev/null 2>&1 || true
    rm -f /etc/systemd/system/gnss-caster-maintenance.socket /etc/systemd/system/gnss-caster-maintenance@.service
    systemctl reset-failed gnss-caster >/dev/null 2>&1 || true

    echo "Removing systemd unit..."
    rm -f "$SERVICE"
    rm -rf /etc/systemd/system/gnss-caster.service.d
    systemctl daemon-reload >/dev/null 2>&1 || true

    echo "Removing Nginx site config..."
    rm -f "$NGINX_ENABLED" "$NGINX_AVAILABLE" "$NGINX_SECURITY_CONF"
    # Restore the distribution's default site if the installer disabled it.
    if [ -f "$BASE/.nginx-default-was-symlink" ] && [ -e /etc/nginx/sites-available/default ]; then
        ln -sf /etc/nginx/sites-available/default /etc/nginx/sites-enabled/default 2>/dev/null || true
    fi
    if [ -f "$BASE/.nginx-default-was-file" ] && [ -e /etc/nginx/sites-enabled/default.gnss-caster.disabled ]; then
        mv -f /etc/nginx/sites-enabled/default.gnss-caster.disabled /etc/nginx/sites-enabled/default 2>/dev/null || true
    fi
    nginx -t >/dev/null 2>&1 && (systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1) || true

    echo "Removing UFW application profile..."
    rm -f "$UFW_APP_PROFILE"

    echo "Removing fail2ban hardening rules..."
    rm -f "$FAIL2BAN_FILTER" "$FAIL2BAN_JAIL"
    systemctl restart fail2ban >/dev/null 2>&1 || true

    echo "Removing cron jobs and cert renew task..."
    remove_gnss_cron_jobs
    rm -f /etc/cron.d/gnss-caster-cert-renew

    echo "Removing logrotate configuration..."
    rm -f /etc/logrotate.d/gnss-caster

    if [ "$PURGE_DATA" != "1" ]; then
        uninstall_safety_backup
    fi

    echo "Removing application files and logs..."
    rm -rf "$BASE" "$LOG_DIR" /etc/gnss-caster
    rm -f "$SELF_SIGNED_CERT" "$SELF_SIGNED_KEY"
    rm -f "$SUDOERS_FILE"
    rm -f "$POLKIT_RULE"
    # The dedicated secret directory was removed with /etc/gnss-caster above,
    # but also remove explicitly in case path was customised.
    rm -f "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    userdel "$SERVICE_USER" >/dev/null 2>&1 || true
    groupdel "$SERVICE_GROUP" >/dev/null 2>&1 || true

    echo ""
    echo "Uninstall completed."
    echo "Removed: service, app code, logs, nginx site, cron tasks, logrotate, nginx hardening, fail2ban rules, UFW profile."
    if [ "$PURGE_DATA" = "1" ]; then
        echo "Removed: instance data, database, and backups (purge mode)."
    else
        echo "Removed: /opt/gnss-caster."
        echo "Data safety backup saved under /var/backups/gnss-caster (safe mode)."
    fi
    echo "Note: system packages were NOT removed."
}

# Read a KEY="value" or KEY=value line from secret.env, returning the value.
read_secret_env_value() {
    local key="$1"
    local file="$2"
    local raw=""

    [ -f "$file" ] || return 0

    raw=$(sed -n "s/^${key}=//p" "$file" | head -n 1)
    # Strip optional surrounding double quotes.
    raw="${raw%\"}"
    raw="${raw#\"}"
    printf '%s' "$raw"
}

manage_secret_files() {
    python3 -I - "$1" "$SECRET_DIR" "$LEGACY_SECRET_KEY_ENV_FILE" << 'PY_SECRET_MIGRATION'
import os
from pathlib import Path
import stat
import sys
import tempfile

def migrate_secrets(mode, secure_path, legacy_path):
    if mode not in ('migrate', 'cleanup'):
        raise ValueError('Invalid secret operation')
    secure = Path(secure_path)
    legacy = Path(legacy_path)
    def read_private(path):
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
                raise ValueError('Unsafe secret file')
            with os.fdopen(fd, 'rb') as handle:
                fd = -1
                data = handle.read(65537)
            if len(data) > 65536:
                raise ValueError('Secret file too large')
            return data
        finally:
            if fd >= 0:
                os.close(fd)
    def publish(path, data):
        if path.exists() or path.is_symlink():
            if read_private(path) != data:
                raise ValueError('Conflicting secret backup; original preserved')
            os.chmod(path, 0o600)
            return
        fd, temporary = tempfile.mkstemp(prefix='.secret-', dir=secure)
        try:
            with os.fdopen(fd, 'wb') as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    # /etc/gnss-caster and its secrets child must not be service-controlled.
    for directory in (secure.parent, secure):
        directory.mkdir(mode=0o700, parents=False, exist_ok=True)
        info = directory.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
            raise ValueError('Unsafe secret directory')
        os.chmod(directory, 0o700)
    sources = sorted(legacy.parent.glob('secret.env.bak-*'))
    if legacy.exists() or legacy.is_symlink():
        sources.insert(0, legacy)
    for source in sources:
        destination = secure / ('legacy-secret.env' if source == legacy else source.name)
        data = read_private(source)
        if mode == 'migrate':
            publish(destination, data)
            if source == legacy and not (secure / 'secret.env').exists():
                publish(secure / 'secret.env', data)
        else:
            if read_private(destination) != data:
                raise ValueError('Legacy secret changed; refusing deletion')
            source.unlink()
    current = secure / 'secret.env'
    if current.exists() or current.is_symlink():
        read_private(current)
        os.chmod(current, 0o600)

if __name__ == '__main__':
    try:
        migrate_secrets(*sys.argv[1:])
    except Exception:
        print('ERROR: Secret migration failed; original files preserved where possible', file=sys.stderr)
        sys.exit(1)
PY_SECRET_MIGRATION
}

run_rotate_secrets() {
    # Rotate the Flask SECRET_KEY (and optionally the Bluetooth pairing PIN)
    # without reinstalling. Generates a fresh 256-bit key, rewrites the
    # secret.env EnvironmentFile (kept mode 0600, outside the systemd unit) and
    # restarts the service. Rotating SECRET_KEY invalidates existing sessions by
    # design, so all users must log in again afterwards.
    echo "=== GNSS CASTER SECRET ROTATION MODE ==="

    if [ ! -d "$INST" ]; then
        echo "ERROR: Instance directory not found: $INST"
        echo "Run installation first."
        exit 1
    fi

    if ! command -v openssl >/dev/null 2>&1; then
        echo "ERROR: openssl is required to rotate the secret key."
        exit 1
    fi

    manage_secret_files migrate

    local new_secret_key
    local current_bt_default_pin
    local current_bt_fallback_pins
    local current_bt_auto_accept
    local current_bt_allowed_devices
    local rotate_bt_pin=0
    local backup_secret_file

    new_secret_key=$(openssl rand -hex 32)

    # Preserve existing Bluetooth settings unless explicitly overridden via env.
    current_bt_default_pin=$(read_secret_env_value "BT_DEFAULT_PIN" "$SECRET_KEY_ENV_FILE")
    current_bt_fallback_pins=$(read_secret_env_value "BT_FALLBACK_PINS" "$SECRET_KEY_ENV_FILE")
    current_bt_auto_accept=$(read_secret_env_value "BT_AUTO_ACCEPT" "$SECRET_KEY_ENV_FILE")
    current_bt_allowed_devices=$(read_secret_env_value "BT_ALLOWED_DEVICES" "$SECRET_KEY_ENV_FILE")

    [ -n "$current_bt_default_pin" ] || current_bt_default_pin="$BT_DEFAULT_PIN"
    [ -n "$current_bt_fallback_pins" ] || current_bt_fallback_pins="$BT_FALLBACK_PINS"
    [ -n "$current_bt_auto_accept" ] || current_bt_auto_accept="$BT_AUTO_ACCEPT"
    if [ -z "$current_bt_allowed_devices" ]; then
        current_bt_allowed_devices="$BT_ALLOWED_DEVICES"
    fi

    # Optional Bluetooth PIN rotation when a new PIN is provided.
    if [ -n "${GNSS_CASTER_BT_DEFAULT_PIN:-}" ]; then
        current_bt_default_pin="$GNSS_CASTER_BT_DEFAULT_PIN"
        rotate_bt_pin=1
    fi
    if [ -n "${GNSS_CASTER_BT_FALLBACK_PINS:-}" ]; then
        current_bt_fallback_pins="$GNSS_CASTER_BT_FALLBACK_PINS"
        rotate_bt_pin=1
    fi

    # Keep a one-time backup of the previous secret file for emergency recovery.
    if [ -f "$SECRET_KEY_ENV_FILE" ]; then
        backup_secret_file="${SECRET_KEY_ENV_FILE}.bak-$(date +%Y%m%d_%H%M%S)"
        cp -a "$SECRET_KEY_ENV_FILE" "$backup_secret_file" 2>/dev/null || true
        chmod 600 "$backup_secret_file" 2>/dev/null || true
    fi

    mkdir -p "$INST"
    {
        printf 'SECRET_KEY=%s\n' "$new_secret_key"
        printf 'BT_DEFAULT_PIN="%s"\n' "$current_bt_default_pin"
        printf 'BT_FALLBACK_PINS="%s"\n' "$current_bt_fallback_pins"
        printf 'BT_AUTO_ACCEPT="%s"\n' "$current_bt_auto_accept"
        printf 'BT_ALLOWED_DEVICES="%s"\n' "$current_bt_allowed_devices"
    } > "$SECRET_KEY_ENV_FILE"
    chmod 600 "$SECRET_KEY_ENV_FILE"
    chown root:root "$SECRET_KEY_ENV_FILE" 2>/dev/null || true

    # Ensure no stale plaintext secret remains in config.yaml.
    if [ -f "$INST/config.yaml" ]; then
        sed -i 's|^\([[:space:]]*secret_key:\).*|\1 ""|' "$INST/config.yaml" 2>/dev/null || true
    fi

    if [ -f "$SERVICE" ]; then
        sed -i "s|^EnvironmentFile=$LEGACY_SECRET_KEY_ENV_FILE$|EnvironmentFile=$SECRET_KEY_ENV_FILE|" "$SERVICE"
        systemctl daemon-reload
    fi
    local service_restart_status="not attempted"
    if [ -f "$SERVICE" ] && command -v systemctl >/dev/null 2>&1; then
        if systemctl restart gnss-caster >/dev/null 2>&1; then
            service_restart_status="ok"
            manage_secret_files cleanup
        else
            service_restart_status="failed"
        fi
    fi

    echo ""
    echo "Secret rotation completed."
    echo "SECRET_KEY: rotated"
    if [ "$rotate_bt_pin" -eq 1 ]; then
        echo "Bluetooth PIN: rotated"
    else
        echo "Bluetooth PIN: unchanged (set GNSS_CASTER_BT_DEFAULT_PIN to rotate)"
    fi
    echo "Secret file: $SECRET_KEY_ENV_FILE (mode 600)"
    if [ -n "${backup_secret_file:-}" ]; then
        echo "Previous secret backup: $backup_secret_file"
        echo "Remove the backup once the new secret is confirmed working."
    fi
    echo "Service restart: $service_restart_status"
    echo "Note: all active web sessions are invalidated by the new SECRET_KEY."
}

run_reset_admin_password() {
    echo "=== GNSS CASTER ADMIN PASSWORD RESET MODE ==="
    echo "Resetting built-in admin password..."

    if [ ! -x "$VENV/bin/python" ]; then
        echo "ERROR: Installed Python runtime not found: $VENV/bin/python"
        echo "Run installation first."
        exit 1
    fi

    if [ ! -f "$INST/config.yaml" ] || [ ! -f "$APP/web/factory.py" ]; then
        echo "ERROR: GNSS Caster installation not found under $BASE"
        echo "Run installation first."
        exit 1
    fi

    migrate_bootstrap_admin_password_location

    local reset_admin_py
    local reset_output
    local reset_admin_username
    local reset_admin_password_file
    local reset_admin_status
    local service_restart_status="not attempted"

    reset_admin_py=$(mktemp /tmp/gnss-caster-reset-admin.XXXXXX.py)

cat > "$reset_admin_py" << 'EOF'
import os
import sys
import time
import secrets
import yaml

sys.path.insert(0, '/opt/gnss-caster')

from app.web.factory import create_app, bcrypt
from app.db.models import db, Admin, write_private_text

CONFIG_PATH = '/opt/gnss-caster/instance/config.yaml'

def load_default_admin_username():
    try:
        with open(CONFIG_PATH, 'r', encoding='utf-8') as config_file:
            config = yaml.safe_load(config_file) or {}
    except Exception:
        config = {}

    return str(
        os.environ.get('GNSS_CASTER_RESET_ADMIN_USERNAME')
        or config.get('security', {}).get('admin_default_user')
        or 'admin'
    ).strip() or 'admin'

def write_bootstrap_file(path, username, password):
    write_private_text(path,
        '# GNSS Caster bootstrap admin credentials\n'
        f'username={username}\n'
        f'password={password}\n'
        'reason=reset\n'
        f'generated_at={int(time.time())}\n'
    )

app = create_app()

with app.app_context():
    db.create_all()

    username = load_default_admin_username()
    password = secrets.token_urlsafe(18)
    password_file_path = str(
        os.environ.get('GNSS_CASTER_BOOTSTRAP_PASSWORD_FILE')
        or app.config.get('BOOTSTRAP_ADMIN_PASSWORD_FILE')
        or '/opt/gnss-caster/instance/initial-admin-password'
    ).strip() or '/opt/gnss-caster/instance/initial-admin-password'

    admin_user = Admin.query.filter_by(username=username).first()
    status = 'updated'
    password_hash = bcrypt.generate_password_hash(password).decode()
    now_ts = int(time.time())

    if admin_user is None:
        admin_user = Admin(
            username=username,
            password=password_hash,
            role='admin',
            email='admin@gnss-caster.local',
            last_login=0,
            login_attempts=0,
            locked_until=0,
            must_change_password=True,
            created_at=now_ts,
            updated_at=now_ts,
        )
        db.session.add(admin_user)
        status = 'created'
    else:
        admin_user.set_password_hash(password_hash)
        admin_user.login_attempts = 0
        admin_user.locked_until = 0
        admin_user.must_change_password = True
        admin_user.updated_at = now_ts

    db.session.commit()
    write_bootstrap_file(password_file_path, username, password)

    print(f'RESET_ADMIN_STATUS={status}')
    print(f'RESET_ADMIN_USERNAME={username}')
    print(f'RESET_ADMIN_PASSWORD_FILE={password_file_path}')
EOF

    if ! reset_output=$(
        GNSS_CASTER_BOOTSTRAP_PASSWORD_FILE="$BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$VENV/bin/python" "$reset_admin_py"
    ); then
        rm -f "$reset_admin_py"
        echo "ERROR: Unable to reset admin password"
        exit 1
    fi

    rm -f "$reset_admin_py"

    reset_admin_status=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_STATUS=//p' | head -n1)
    reset_admin_username=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_USERNAME=//p' | head -n1)
    reset_admin_password_file=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_PASSWORD_FILE=//p' | head -n1)

    if [ -n "${reset_admin_password_file:-}" ] && [ -f "$reset_admin_password_file" ]; then
        chown root:"$SERVICE_GROUP" "$reset_admin_password_file" 2>/dev/null || true
        chmod 640 "$reset_admin_password_file" 2>/dev/null || true
    fi

    if [ -f "$SERVICE" ] && command -v systemctl >/dev/null 2>&1; then
        if systemctl restart gnss-caster >/dev/null 2>&1; then
            service_restart_status="ok"
        else
            service_restart_status="failed"
        fi
    fi

    echo ""
    echo "Admin password reset completed."
    echo "Account status: ${reset_admin_status:-updated}"
    echo "Default credentials: ${reset_admin_username:-admin} / <see file>"
    echo "Credentials file: ${reset_admin_password_file:-$BOOTSTRAP_ADMIN_PASSWORD_FILE}"
    echo "Show password: sudo cat ${reset_admin_password_file:-$BOOTSTRAP_ADMIN_PASSWORD_FILE}"
    echo "Service restart: $service_restart_status"
}

capture_diagnostic_shell() {
    local output_file="$1"
    shift
    local command_text="$*"
    local command_status

    {
        echo "$ $command_text"
        echo ""
    } > "$output_file" 2>&1

    # Use a non-login, non-interactive shell with a fixed PATH. The command
    # strings are built by this installer (not from external input), and
    # avoiding a login shell prevents profile side effects from altering output.
    set +e
    PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin" \
        /bin/bash --noprofile --norc -c "$command_text" >> "$output_file" 2>&1
    command_status=$?
    set -e

    {
        echo ""
        echo "[exit_status=$command_status]"
    } >> "$output_file" 2>&1
}

print_service_status() {
    local unit_name="$1"
    local active_state="unavailable"
    local enabled_state="unavailable"

    if command -v systemctl >/dev/null 2>&1; then
        active_state=$(systemctl is-active "$unit_name" 2>/dev/null || true)
        enabled_state=$(systemctl is-enabled "$unit_name" 2>/dev/null || true)
    fi

    printf '  %-22s active=%-12s enabled=%s\n' "$unit_name" "$active_state" "$enabled_state"
}

print_cron_file_status() {
    local cron_file="$1"
    local label="$2"

    if [ ! -f "$cron_file" ]; then
        echo "  $label: absent"
        return
    fi

    echo "  $label: present ($cron_file)"
    sed -n '/^[[:space:]]*#/d;/^[[:space:]]*$/d;p' "$cron_file" 2>/dev/null | sed 's/^/    /' || true
}

is_tcp_port_listening() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 1
    fi
    ss -ltn 2>/dev/null | grep -Eq "[:.]${tcp_port}[[:space:]]"
}

show_tcp_port_listeners() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi
    ss -ltnp 2>/dev/null | grep -E "[:.]${tcp_port}[[:space:]]" || true
}

show_tcp_port_process_names() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi

    ss -ltnp 2>/dev/null | grep -E "[:.]${tcp_port}[[:space:]]" | \
        grep -oE '"[^"]+"' | tr -d '"' | sort -u
}

print_network_status() {
    echo ""
    echo "Network:"

    if command -v hostname >/dev/null 2>&1; then
        echo "  host_ips=$(hostname -I 2>/dev/null | xargs echo || true)"
    fi

    if command -v ip >/dev/null 2>&1; then
        echo "  default_route:"
        ip route show default 2>/dev/null | sed 's/^/    /' || echo "    unavailable"

        echo "  active_addresses:"
        ip -brief addr show scope global 2>/dev/null | sed 's/^/    /' || echo "    unavailable"
    else
        echo "  ip command unavailable"
    fi

    if [ -f /etc/resolv.conf ]; then
        echo "  dns:"
        grep -E '^[[:space:]]*nameserver[[:space:]]+' /etc/resolv.conf 2>/dev/null | sed 's/^/    /' || echo "    unavailable"
    fi

    if command -v iw >/dev/null 2>&1; then
        echo "  wifi_links:"
        local wifi_interfaces
        wifi_interfaces=$(iw dev 2>/dev/null | awk '$1=="Interface" {print $2}')
        if [ -n "$wifi_interfaces" ]; then
            for wifi_iface in $wifi_interfaces; do
                echo "    [$wifi_iface]"
                iw dev "$wifi_iface" link 2>/dev/null | sed 's/^/      /' || true
            done
        else
            echo "    no wireless interfaces reported by iw"
        fi
    fi

    if command -v rfkill >/dev/null 2>&1; then
        echo "  rfkill:"
        rfkill list 2>/dev/null | sed 's/^/    /' || true
    fi

    if command -v journalctl >/dev/null 2>&1; then
        echo "  recent network warnings:"
        journalctl \
            -u ssh -u sshd -u NetworkManager -u systemd-networkd -u dhcpcd -u wpa_supplicant \
            --since '30 minutes ago' --no-pager 2>/dev/null | \
            grep -Ei 'disconnect|deauth|carrier|timeout|failed|error|dhcp|wlan|ssh' | \
            tail -n 12 | sed 's/^/    /' || true
    fi
}

print_operational_profile() {
    local systemd_version="unknown"
    local bt_auto_accept
    local bt_allowlist
    local bt_mode="open (auto-accept)"
    local firewall_state="unknown"

    echo ""
    echo "Operational profile:"

    if command -v systemctl >/dev/null 2>&1; then
        systemd_version=$(systemctl --version 2>/dev/null | awk 'NR==1 {print $2}')
        [ -n "$systemd_version" ] || systemd_version="unknown"
    fi
    echo "  systemd_version=$systemd_version"

    if [ -f "$SERVICE" ]; then
        echo "  systemd_hardening:"
        grep -E '^(NoNewPrivileges|ProtectSystem|ProtectHome|ProtectProc|ProcSubset|ReadWritePaths|PrivateTmp|LockPersonality)=' "$SERVICE" 2>/dev/null \
            | sed 's/^/    /' || echo "    unavailable"
    else
        echo "  systemd_hardening=unit not installed"
    fi

    if [ -f "$SECRET_KEY_ENV_FILE" ]; then
        bt_auto_accept=$(read_secret_env_value "BT_AUTO_ACCEPT" "$SECRET_KEY_ENV_FILE")
        bt_allowlist=$(read_secret_env_value "BT_ALLOWED_DEVICES" "$SECRET_KEY_ENV_FILE")
        case "$(printf '%s' "$bt_auto_accept" | tr '[:upper:]' '[:lower:]')" in
            0|false|no|off)
                bt_mode="allowlist only"
                ;;
        esac
        echo "  bluetooth_pairing=$bt_mode"
        if [ -n "$bt_allowlist" ]; then
            echo "  bluetooth_allowlist=$bt_allowlist"
        else
            echo "  bluetooth_allowlist=(none)"
        fi
    else
        echo "  bluetooth_pairing=unknown (secret.env not found)"
    fi

    if command -v ufw >/dev/null 2>&1; then
        firewall_state=$(ufw status 2>/dev/null | awk 'NR==1 {print $2}')
        [ -n "$firewall_state" ] || firewall_state="unknown"
        echo "  firewall(ufw)=$firewall_state"
        if [ "$firewall_state" = "active" ]; then
            ufw status 2>/dev/null | grep -E "(^|[^0-9])$(get_config_value "web_port" "8080")(/| )" \
                | sed 's/^/    /' || true
        fi
    else
        echo "  firewall(ufw)=not installed"
    fi
}

run_status() {
    echo "=== GNSS CASTER STATUS ==="

    local web_port
    local ntrip_port
    local health_url
    local tls_mode_label="HTTP only"

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")

    case "$web_port" in
        ''|*[!0-9]*)
            web_port="8080"
            ;;
    esac
    case "$ntrip_port" in
        ''|*[!0-9]*)
            ntrip_port="2101"
            ;;
    esac

    health_url="http://127.0.0.1:${web_port}/api/health"

    if [ -f "$NGINX_AVAILABLE" ] && grep -Eq 'listen[[:space:]]+443[[:space:]]+ssl' "$NGINX_AVAILABLE"; then
        tls_mode_label="HTTPS enabled"
    fi

    echo ""
    echo "Services:"
    print_service_status "gnss-caster"
    print_service_status "nginx"
    print_service_status "bluetooth"
    print_service_status "fail2ban"
    print_service_status "cron"

    echo ""
    echo "Ports and health:"
    echo "  web_port=$web_port"
    echo "  ntrip_port=$ntrip_port"
    echo "  tls=$tls_mode_label"

    if command -v curl >/dev/null 2>&1; then
        if curl -sS --max-time 5 -f "$health_url" >/dev/null 2>&1; then
            echo "  health=ok ($health_url)"
        else
            echo "  health=failed ($health_url)"
        fi
    else
        echo "  health=unknown (curl not installed)"
    fi

    if is_tcp_port_listening "80" || is_tcp_port_listening "443"; then
        echo "  nginx_public_listeners:"
        show_tcp_port_listeners "80" | sed 's/^/    /'
        show_tcp_port_listeners "443" | sed 's/^/    /'
    else
        echo "  nginx_public_listeners=absent"
    fi

    if is_tcp_port_listening "$web_port"; then
        echo "  web_backend_listener=present"
        show_tcp_port_listeners "$web_port" | sed 's/^/    /'
    else
        echo "  web_backend_listener=absent"
    fi

    if is_tcp_port_listening "$ntrip_port"; then
        echo "  ntrip_listener=present"
        show_tcp_port_listeners "$ntrip_port" | sed 's/^/    /'
    else
        echo "  ntrip_listener=absent"
    fi

    print_network_status

    echo ""
    echo "Web-managed settings:"
    if [ -f "$INST/db.sqlite" ] && command -v sqlite3 >/dev/null 2>&1; then
        sqlite3 "$INST/db.sqlite" \
            "SELECT key || '=' || value FROM system_setting WHERE key IN ('ntrip_enabled','bluetooth_enabled','bluetooth_discoverable','auto_backup','backup_interval','log_retention','data_retention','max_connections') ORDER BY key;" \
            2>/dev/null | sed 's/^/  /' || echo "  unavailable"
    else
        echo "  unavailable (database or sqlite3 not found)"
    fi

    echo ""
    echo "Cron:"
    print_cron_file_status "$MAINTENANCE_CRON" "maintenance"
    print_cron_file_status "$BACKUP_CRON" "backup"

    echo ""
    echo "Fail2ban:"
    if command -v fail2ban-client >/dev/null 2>&1; then
        fail2ban-client status 2>/dev/null | sed 's/^/  /' || echo "  unavailable"
    else
        echo "  fail2ban-client not installed"
    fi

    print_operational_profile

    echo ""
    echo "Recent app warnings/errors:"
    if [ -f "$LOG_DIR/app.log" ]; then
        grep -Ei 'error|warning|failed|traceback' "$LOG_DIR/app.log" 2>/dev/null | tail -n 10 | sed 's/^/  /' || true
    else
        echo "  app log not found"
    fi
}

write_install_report() {
    mkdir -p "$INST"

    cat > "$INSTALL_REPORT" << EOF
GNSS Caster installation report
Generated at: $(date -Is 2>/dev/null || date)
Host: $(hostname 2>/dev/null || echo unknown)

Access:
  Web Interface: ${WEB_SCHEME:-http}://${WEB_HOST:-127.0.0.1}/
  API Endpoint: ${WEB_SCHEME:-http}://${WEB_HOST:-127.0.0.1}/api/
  NTRIP Server: ${IP_ADDRESS:-127.0.0.1}:${INSTALL_NTRIP_PORT:-2101}

Runtime Profile:
  TLS mode: ${TLS_MODE:-none}
  TLS domain: ${TLS_DOMAIN:-}
  Web backend bind: 127.0.0.1:${INSTALL_WEB_PORT} (private, behind nginx)
  NTRIP bind: 0.0.0.0:${INSTALL_NTRIP_PORT} (public)
  Bluetooth pairing: $([ "$BT_AUTO_ACCEPT" = "1" ] && echo "open (auto-accept)" || echo "allowlist only")
  Fail2ban: $([ "$ENABLE_FAIL2BAN" = "1" ] && echo enabled || echo disabled)
  Monitor auto-recovery: disabled by default
  Health watchdog cron: ${WATCHDOG_CRON_STATUS:-disabled}
  Weekly auto-update cron: $([ "$ENABLE_AUTO_UPDATE" = "1" ] && echo enabled || echo disabled)
  Automatic backup cron: ${BACKUP_CRON_STATUS:-unknown}
  Log retention: ${LOGROTATE_STATUS:-unknown}

Files:
  Bootstrap credentials file: $BOOTSTRAP_ADMIN_PASSWORD_FILE
  Status command: sudo /opt/gnss-caster/status.sh
  Diagnostics command: sudo /opt/gnss-caster/diagnose.sh
  Repair command: sudo /opt/gnss-caster/repair.sh
  Watchdog command: sudo /opt/gnss-caster/watchdog.sh
