prepare_runtime_port() {
    local port_label="$1"
    local tcp_port="$2"

    echo "Checking for processes using $port_label port $tcp_port..."
    if ! is_tcp_port_listening "$tcp_port"; then
        return 0
    fi

    echo "WARNING: $port_label TCP port $tcp_port is already listening."
    show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'

    if command -v systemctl >/dev/null 2>&1 && systemctl is-active --quiet gnss-caster; then
        echo "Stopping existing gnss-caster service to release $port_label port $tcp_port..."
        systemctl stop gnss-caster >/dev/null 2>&1 || true
        sleep 2

        if ! is_tcp_port_listening "$tcp_port"; then
            echo "$port_label port $tcp_port was released by stopping gnss-caster."
            return 0
        fi

        echo "$port_label port $tcp_port is still occupied after stopping gnss-caster."
        show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
    fi

    if [ "$FORCE_PORT_KILL" = "1" ]; then
        local listener_names
        local listener_name
        local kill_allowed=1

        listener_names=$(show_tcp_port_process_names "$tcp_port")
        if [ -n "$listener_names" ]; then
            while IFS= read -r listener_name; do
                [ -n "$listener_name" ] || continue
                case "$listener_name" in
                    python|python3|gnss-caster|waitress-serve|gunicorn)
                        ;;
                    *)
                        kill_allowed=0
                        ;;
                esac
            done << EOF
$listener_names
EOF
        fi

        if [ "$kill_allowed" -ne 1 ]; then
            echo "ERROR: Refusing to kill non-GNSS processes on $port_label port $tcp_port."
            echo "Current listeners:"
            show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
            echo "Use a different port or stop conflicting services manually."
            exit 1
        fi

        echo "GNSS_CASTER_FORCE_PORT_KILL=1 set; killing GNSS-related listeners on $port_label port $tcp_port."
        fuser -k "${tcp_port}/tcp" || true
        sleep 2

        if ! is_tcp_port_listening "$tcp_port"; then
            echo "$port_label port $tcp_port was released after forced kill."
            return 0
        fi

        echo "ERROR: $port_label port $tcp_port is still occupied after forced kill."
        show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
        exit 1
    fi

    echo "ERROR: $port_label port $tcp_port is occupied and will not be killed automatically."
    echo "Free the port manually, choose a different GNSS_CASTER_WEB_PORT/GNSS_CASTER_NTRIP_PORT, or rerun with GNSS_CASTER_FORCE_PORT_KILL=1."
    exit 1
}

write_systemd_service_unit() {
    local systemd_version=0
    local optional_hardening=""

    if command -v systemctl >/dev/null 2>&1; then
        systemd_version=$(systemctl --version 2>/dev/null | awk 'NR==1 {print $2}')
        case "$systemd_version" in
            ''|*[!0-9]*)
                systemd_version=0
                ;;
        esac
    fi

    # ProtectProc/ProcSubset require systemd >= 247 (Debian Bullseye+).
    # On older systemd they are unknown directives and break the unit, so
    # only emit them when supported.
    if [ "$systemd_version" -ge 247 ]; then
        optional_hardening=$'ProtectProc=invisible\nProcSubset=pid\n'
    fi

cat > "$SERVICE" << EOF
[Unit]
Description=GNSS Caster Service
After=network-online.target bluetooth.target nginx.target gnss-caster-maintenance.socket
Wants=network-online.target gnss-caster-maintenance.socket
StartLimitIntervalSec=300
StartLimitBurst=10

[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_GROUP
SupplementaryGroups=dialout tty bluetooth
WorkingDirectory=$BASE
RuntimeDirectory=gnss-caster
RuntimeDirectoryMode=0700
Environment="PATH=$VENV/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
Environment="PYTHONPATH=$BASE"
# SECRET_KEY and Bluetooth PINs are loaded from a mode-600 file so they are
# not exposed via `systemctl show gnss-caster`.
EnvironmentFile=$SECRET_KEY_ENV_FILE
Environment="PYTHONUNBUFFERED=1"
# Live Bluetooth RSSI, read over HCI from the established link. Set to 0 to
# disable if a particular adapter turns out to dislike being queried.
Environment="GNSS_CASTER_LIVE_RSSI=${ENABLE_LIVE_RSSI:-1}"
# How often station counters are persisted. Higher means fewer SD-card writes;
# lower means fresher totals in the UI. Minimum 5 seconds.
Environment="GNSS_CASTER_DB_FLUSH_SECONDS=${DB_FLUSH_SECONDS:-30}"
ExecStartPre=+/usr/bin/python3 -I /var/lib/gnss-caster-maintenance/recovery.py boot-check
ExecStartPre=/usr/bin/test -x $VENV/bin/python
ExecStartPre=/usr/bin/test -f $BASE/main.py
ExecStart=$VENV/bin/python $BASE/main.py
Restart=on-failure
RestartSec=5
TimeoutStartSec=60
TimeoutStopSec=20
KillMode=mixed
LimitNOFILE=65535
TasksAccounting=yes
TasksMax=512
MemoryAccounting=yes
# The service cannot gain privileges through exec; maintenance uses typed IPC.
NoNewPrivileges=yes
PrivateTmp=yes
# Use 'full' by default for broader compatibility across distros/packages.
# 'strict' can break runtime behavior in some environments where components
# still expect limited writable access outside explicit paths.
ProtectSystem=full
ProtectClock=yes
ProtectHostname=yes
${optional_hardening}ReadWritePaths=$INST $BACKUP_DIR $LOG_DIR
ProtectHome=yes
ProtectControlGroups=yes
ProtectKernelModules=yes
ProtectKernelTunables=yes
LockPersonality=yes
RestrictSUIDSGID=yes
UMask=0077

# Logging
StandardOutput=append:$LOG_DIR/app.log
StandardError=append:$LOG_DIR/error.log
SyslogIdentifier=gnss-caster

[Install]
WantedBy=multi-user.target
EOF

    strip_crlf "$SERVICE"
}

