                # Bare IDs from older releases are deliberately invalidated.
                admin_id, version = str(user_id).split(':', 1)
                user = Admin.query.get(int(admin_id))
                if user is not None and int(version) == int(user.session_version or 0):
                    return user
                return None
            except Exception as e:
                logger.error(f"Error loading user: {e}")
                return None

        def _should_show_password_change_notice(username_hint=''):
            """Show login warning only for accounts flagged to change password."""
            try:
                username_value = str(username_hint or '').strip()
                if username_value:
                    admin_user = Admin.query.filter_by(username=username_value).first()
                    return bool(
                        admin_user and getattr(admin_user, 'must_change_password', False)
                    )

                built_in_admin = Admin.query.order_by(Admin.id.asc()).first()
                if not built_in_admin:
                    return False

                return bool(getattr(built_in_admin, 'must_change_password', False))
            except Exception as notice_error:
                logger.warning(
                    f"Unable to evaluate password-change notice state: {notice_error}"
                )
