cat > $BASE/main.py << 'EOF'
#!/usr/bin/env python3
"""
GNSS Caster - Main Application Entry Point
"""
import os
import subprocess
import sys
import logging
import threading
import time
import tempfile
import yaml
from waitress import serve

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
CONFIG_PATH = os.path.join(BASE_DIR, 'instance', 'config.yaml')

def _normalize_log_level(raw_level, default_level='INFO'):
    normalized_level = str(raw_level or '').strip().upper()
    if normalized_level in ('CRITICAL', 'ERROR', 'WARNING', 'INFO', 'DEBUG'):
        return normalized_level
    return str(default_level or 'INFO').strip().upper()

def _load_runtime_config():
    try:
        with open(CONFIG_PATH, 'r', encoding='utf-8') as config_file:
            return yaml.safe_load(config_file) or {}
    except Exception:
        return {}

runtime_config = _load_runtime_config()
runtime_server_config = runtime_config.get('server', {}) or {}
runtime_logging_config = runtime_config.get('logging', {}) or {}
runtime_debug_enabled = bool(runtime_server_config.get('debug', False))
runtime_log_level_name = _normalize_log_level(
    runtime_logging_config.get(
        'level',
        'DEBUG' if runtime_debug_enabled else 'INFO'
    )
)

logging.basicConfig(
    level=getattr(logging, runtime_log_level_name, logging.INFO),
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
    handlers=[
        # Only a file handler here. The systemd unit already routes stdout to
        # this same app.log (StandardOutput=append:), so also attaching a
        # StreamHandler(sys.stdout) made every line appear twice - and had two
        # independent writers appending to one file.
        logging.FileHandler('/var/log/gnss-caster/app.log')
    ],
    force=True,
)

logger = logging.getLogger(__name__)

from app.web.factory import create_app
from app.version import __version__
from app.db.models import SystemSetting
from app.bluetooth.core import bluetooth_manager
from app.ntrip.core import ntrip_server
from app.rtcm.stream import stream_manager

def _get_web_bind_host(app):
    return str(
        app.config.get('WEB_HOST')
        or runtime_server_config.get('web_host')
        or '127.0.0.1'
    ).strip() or '127.0.0.1'

def _get_ntrip_bind_host(app):
    return str(
        app.config.get('NTRIP_HOST')
        or runtime_server_config.get('ntrip_host')
        or app.config.get('HOST')
        or runtime_server_config.get('host')
        or '0.0.0.0'
    ).strip() or '0.0.0.0'

def _get_web_port(app):
    try:
        return int(
            app.config.get('WEB_PORT')
            or runtime_server_config.get('web_port')
            or 8080
        )
    except (TypeError, ValueError):
        return 8080

def _get_ntrip_port(app):
    try:
        return int(
            app.config.get('NTRIP_PORT')
            or runtime_server_config.get('ntrip_port')
            or 2101
        )
    except (TypeError, ValueError):
        return 2101

def _get_system_setting_value(app, key, default_value=''):
    try:
        with app.app_context():
            setting = SystemSetting.query.filter_by(key=str(key)).first()
            if setting and setting.value is not None:
                return setting.value
    except Exception as setting_error:
        logger.warning(f"Unable to read system setting {key}: {setting_error}")

    return default_value

def _is_system_setting_enabled(app, key, default_value=True):
    default_text = 'true' if bool(default_value) else 'false'
    return str(
        _get_system_setting_value(app, key, default_text)
    ).strip().lower() in ('1', 'true', 'yes', 'on')

def _get_max_connections(app):
    try:
        configured_value = int(
            _get_system_setting_value(app, 'max_connections', '100') or 100
        )
    except (TypeError, ValueError):
        configured_value = 100

    return max(1, min(int(configured_value), 1000))

def _configure_ntrip_server(app):
    ntrip_server.init_app(app)
    ntrip_server.host = _get_ntrip_bind_host(app)
    ntrip_server.port = _get_ntrip_port(app)
    ntrip_server.max_connections = _get_max_connections(app)

def start_services(app):
    """Start all background services with app context"""
    bluetooth_manager.init_app(app)
    if _is_system_setting_enabled(app, 'bluetooth_enabled', True):
        try:
            logger.info("Starting Bluetooth manager...")
            bluetooth_manager.start()
            logger.info("Bluetooth manager started")
        except Exception as e:
            logger.error(f"Failed to start Bluetooth manager: {e}")
    else:
        logger.info("Bluetooth manager disabled by system settings")
    
    _configure_ntrip_server(app)
    if _is_system_setting_enabled(app, 'ntrip_enabled', True):
        try:
            logger.info("Starting NTRIP server...")
            ntrip_server.start()
            logger.info("NTRIP server started")
        except Exception as e:
            logger.error(f"Failed to start NTRIP server: {e}")
    else:
        logger.info("NTRIP server disabled by system settings")

    # Start DB maintenance thread (Fix #6: prune log_entry + command_log rows)
    _start_db_maintenance(app)

    try:
        from app import notify as _notify
        _notify.start_outbox(app)
    except Exception:
        logger.warning('Telegram outbox not started; check storage and permissions')

    # Telegram command poller. It idles cheaply while disabled, so enabling
    # commands later does not require a service restart.
    try:
        from app import notify as _notify
        _notify.start_command_poller(app)
    except Exception as notify_error:
        logger.warning(f"Telegram command poller not started: {notify_error}")


def _prune_position_samples(app, keep_days=30):
    """Drop position history older than the retention window."""
    try:
        from app.db.models import PositionSample, db

        cutoff = int(time.time()) - keep_days * 86400
        with app.app_context():
            removed = (
                PositionSample.query
                .filter(PositionSample.ts < cutoff)
                .delete(synchronize_session=False)
            )
            db.session.commit()
            if removed:
                logger.info(f"Pruned {removed} position samples older than {keep_days} days")
    except Exception as prune_error:
        logger.warning(f"Could not prune position samples: {prune_error}")


def _verify_latest_backup(app):
    """Read the newest archive end to end and complain if it is unreadable.

    A backup nobody has opened is a promise, not a guarantee: flash media rots
    quietly and a corrupt archive looks exactly like a good one in a listing.
    Checking on a schedule means the bad news arrives while there is still time
    to make another copy, rather than during a restore.
    """
    backup_dir = '/opt/gnss-caster/backups'
    if not os.path.isdir(backup_dir):
        return

    archives = [
        os.path.join(backup_dir, name)
        for name in os.listdir(backup_dir)
        if name.startswith('backup_') and name.endswith(('.tar.gz', '.tar.gz.enc'))
    ]
    if not archives:
        return

    newest = max(archives, key=os.path.getmtime)
    # Do not re-check the same file over and over; once a day is plenty.
    age_hours = (time.time() - os.path.getmtime(newest)) / 3600.0
    last_checked = getattr(_verify_latest_backup, '_last_checked', None)
    if last_checked == newest and age_hours > 24:
        return

    verify_path = newest
    temp_plain_path = ''
    try:
        if newest.endswith('.enc'):
            with app.app_context():
                setting = SystemSetting.query.filter_by(
                    key='backup_encryption_passphrase'
                ).first()
                passphrase = str(setting.value or '') if setting else ''

            if not passphrase:
                logger.warning(
                    f'Encrypted backup verification skipped for {os.path.basename(newest)}: '
                    'no current backup passphrase is stored'
                )
                return

            with tempfile.NamedTemporaryFile(
                prefix='gnss-caster-maint-verify-', suffix='.tar.gz', delete=False
            ) as temp_plain:
                temp_plain_path = temp_plain.name

            decrypt_env = os.environ.copy()
            decrypt_env['PASSPHRASE'] = passphrase
            decrypt_result = subprocess.run(
                [
                    'openssl', 'enc', '-d', '-aes-256-cbc', '-pbkdf2',
                    '-iter', '200000', '-in', newest,
                    '-out', temp_plain_path, '-pass', 'env:PASSPHRASE'
                ],
                capture_output=True, text=True, timeout=300, env=decrypt_env,
            )
            if decrypt_result.returncode != 0:
                logger.error(
                    f'Encrypted backup verification FAILED for {os.path.basename(newest)}: '
                    'decryption failed with the current passphrase'
                )
                result = decrypt_result
            else:
                verify_path = temp_plain_path
                result = subprocess.run(
                    ['tar', '-tzf', verify_path],
                    capture_output=True, text=True, timeout=300,
                )
        else:
            result = subprocess.run(
                ['tar', '-tzf', verify_path],
                capture_output=True, text=True, timeout=300,
            )
    except Exception as verify_error:
        logger.warning(f"Backup verification could not run: {verify_error}")
        return
    finally:
        if temp_plain_path:
            try:
                os.unlink(temp_plain_path)
            except OSError:
                pass

    _verify_latest_backup._last_checked = newest
    name = os.path.basename(newest)

    if result.returncode == 0:
        logger.info(f"Backup verification passed: {name}")
        return

    logger.error(f"Backup verification FAILED for {name}: {(result.stderr or '').strip()[:200]}")
    try:
        from app import notify as _notify
        _notify.send(
            app,
            f'\u274c GNSS Caster: backup "{name}" is unreadable. '
            'Create a fresh backup and check the storage media.',
            event='notify_backup',
            event_key='backup-verify-failed',
            cooldown=21600.0,
        )
    except Exception:
        pass


def _start_db_maintenance(app):
    """Spawn a low-priority background thread that periodically prunes stale
    DB rows so SQLite never grows unbounded.

    Intervals and retention windows are read from SystemSetting at each run
    so the admin can change them in the UI without restarting the service.

    Pruning schedule:
      • log_entry  – honour the existing 'log_retention' setting (days)
      • command_log – honour a new 'command_log_retention' setting (days,
                       default 90); hard-capped to keep the last 10 000 rows
                       per station regardless of age.
    The thread wakes every 6 hours so the worst-case DB growth between runs
    is bounded even under heavy load.
    """
    def _db_maintenance_loop():
        # Stagger the first run by 10 minutes so it doesn't compete with
        # the initial BT-scan / NTRIP-startup I/O burst.
        time.sleep(600)

        while True:
            try:
                with app.app_context():
                    _prune_log_entry(app)
                    _prune_command_log(app)
                    _prune_position_samples(app)
                _verify_latest_backup(app)
            except Exception as _maint_err:
                logger.error(f"DB maintenance error: {_maint_err}")

            # Run every 6 hours
            time.sleep(6 * 3600)

    t = threading.Thread(
        target=_db_maintenance_loop,
        daemon=True,
        name="DB-Maintenance",
    )
    t.start()
    logger.info("DB maintenance thread started")


def _prune_log_entry(app):
    """Delete log_entry rows older than log_retention days."""
    try:
        retention_days = int(
            _get_system_setting_value(app, 'log_retention', '30') or 30
        )
    except (TypeError, ValueError):
        retention_days = 30
    retention_days = max(1, min(retention_days, 365))

    cutoff = int(time.time()) - retention_days * 86400

    from app.db.models import db, LogEntry
    deleted = (
        db.session.query(LogEntry)
        .filter(LogEntry.timestamp < cutoff)
        .delete(synchronize_session=False)
    )
    if deleted:
        db.session.commit()
        logger.info(f"DB maintenance: pruned {deleted} log_entry rows older than {retention_days}d")
    else:
        db.session.rollback()


def _prune_command_log(app):
    """Delete command_log rows beyond the retention window or row-count cap."""
    try:
        retention_days = int(
            _get_system_setting_value(app, 'command_log_retention', '90') or 90
        )
    except (TypeError, ValueError):
        retention_days = 90
    retention_days = max(1, min(retention_days, 365))

    cutoff = int(time.time()) - retention_days * 86400

    from app.db.models import db, CommandLog, BaseStation
    total_deleted = 0

    # Age-based prune across all stations
    age_deleted = (
        db.session.query(CommandLog)
        .filter(CommandLog.ts < cutoff)
        .delete(synchronize_session=False)
    )
    total_deleted += age_deleted

    # Per-station row-count cap: keep only the most recent 10 000 rows
    cap = 10_000
    for station in BaseStation.query.all():
        count = (
            db.session.query(CommandLog)
            .filter(CommandLog.station_id == station.id)
            .count()
        )
        overflow = count - cap
        if overflow > 0:
            oldest_ids = (
                db.session.query(CommandLog.id)
                .filter(CommandLog.station_id == station.id)
                .order_by(CommandLog.ts.asc())
                .limit(overflow)
                .subquery()
            )
            cap_deleted = (
                db.session.query(CommandLog)
                .filter(CommandLog.id.in_(oldest_ids))
                .delete(synchronize_session=False)
            )
            total_deleted += cap_deleted

    if total_deleted:
        db.session.commit()
        logger.info(
            f"DB maintenance: pruned {total_deleted} command_log rows "
            f"(>{retention_days}d old or >{cap} per station)"
        )
    else:
        db.session.rollback()

def stop_services():
    """Stop all background services"""
    logger.info("Stopping services...")
    
    try:
        ntrip_server.stop()
        logger.info("NTRIP server stopped")
    except Exception as e:
        logger.error(f"Error stopping NTRIP server: {e}")
    
    try:
        bluetooth_manager.stop()
        logger.info("Bluetooth manager stopped")
    except Exception as e:
        logger.error(f"Error stopping Bluetooth manager: {e}")

def monitor_services(app):
    """Monitor and restart services if needed"""
    while True:
        try:
            bluetooth_enabled = _is_system_setting_enabled(app, 'bluetooth_enabled', True)
            bluetooth_threads_alive = any(thread.is_alive() for thread in bluetooth_manager.threads)
            if bluetooth_enabled and (not bluetooth_manager.running or not bluetooth_threads_alive):
                logger.warning("Bluetooth manager is not running, attempting to restart...")
                try:
                    bluetooth_manager.init_app(app)
                    bluetooth_manager.start()
                    logger.info("Bluetooth manager restarted")
                except Exception as e:
                    logger.error(f"Failed to restart Bluetooth manager: {e}")
            elif not bluetooth_enabled and bluetooth_manager.running:
                logger.info("Bluetooth manager disabled by settings; stopping")
                bluetooth_manager.stop()

            # Check NTRIP server
            ntrip_enabled = _is_system_setting_enabled(app, 'ntrip_enabled', True)
            if ntrip_enabled and not ntrip_server.running:
                logger.warning("NTRIP server is not running, attempting to restart...")
                try:
                    _configure_ntrip_server(app)
                    ntrip_server.start()
                    logger.info("NTRIP server restarted")
                except Exception as e:
                    logger.error(f"Failed to restart NTRIP server: {e}")
            elif not ntrip_enabled and ntrip_server.running:
                logger.info("NTRIP server disabled by settings; stopping")
                ntrip_server.stop()
            
            # Clean up inactive streams with app context
            with app.app_context():
                stream_manager.cleanup_inactive()
            
            time.sleep(60)  # Check every minute
            
        except Exception as e:
            logger.error(f"Error in service monitor: {e}")
            time.sleep(30)

def main():
    """Main application entry point"""
    try:
        logger.info(f"Starting GNSS Caster application v{__version__}")
        
        # Create Flask application
        app = create_app()

        logging.getLogger().setLevel(
            getattr(logging, str(app.config.get('LOG_LEVEL', 'INFO')), logging.INFO)
        )
        
        # Start background services with app context
        start_services(app)
        
        # Start service monitor thread
        monitor_thread = threading.Thread(
            target=monitor_services,
            args=(app,),
            daemon=True,
            name="Service-Monitor"
        )
        monitor_thread.start()
        
        # Get configuration
        web_host = _get_web_bind_host(app)
        ntrip_host = _get_ntrip_bind_host(app)
        port = _get_web_port(app)
        ntrip_port = _get_ntrip_port(app)
        
        logger.info(f"Starting web server on {web_host}:{port}")
        logger.info(f"Web interface (local, behind nginx): http://{web_host}:{port}")
        logger.info(f"NTRIP server: {ntrip_host}:{ntrip_port}")
        logger.info("System started successfully")
        try:
            from app import notify as _notify
            _notify.send(
                app,
                f'\u2705 GNSS Caster started (version {__version__}).',
                event='notify_service',
                event_key='service-start',
                cooldown=60.0,
            )
        except Exception:
            pass
        
        # Run application with production WSGI server to avoid long-run instability.
        # SSE endpoints (dashboard live feed, receiver console) each hold a worker
        # thread for the duration of the connection, so we default to a higher
        # thread count than a purely request/response app would need (Fix #18).
        web_threads = int(os.environ.get('WEB_THREADS', '16'))
        connection_limit = int(os.environ.get('WEB_CONNECTION_LIMIT', '200'))

        logger.info(
            f"Starting Waitress server on {web_host}:{port} "
            f"(threads={web_threads}, connection_limit={connection_limit})"
        )
        serve(
            app,
            host=web_host,
            port=port,
            threads=web_threads,
            connection_limit=connection_limit,
            cleanup_interval=30,
            channel_timeout=120,
        )
        
    except KeyboardInterrupt:
        logger.info("Application stopped by user")
        stop_services()
        sys.exit(0)
    except Exception as e:
        logger.error(f"Failed to start application: {e}", exc_info=True)
        stop_services()
        sys.exit(1)

if __name__ == '__main__':
    main()
EOF

chmod +x "$BASE/main.py"

# Legacy fallback entrypoint for stale systemd overrides pointing to /opt/gnss-caster/app/main.py
cat > $APP/main.py << 'EOF'
#!/usr/bin/env python3
